import { test, expect } from '@playwright/test';

test.describe('In-app Notifications - Real-time Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should update notifications in real-time without page refresh', async ({ page }) => {
    // Verify initial state
    const notificationCount = page.getByRole('region', { name: /notifications/i }).count();
    await expect(notificationCount).toBeGreaterThan(0);

    // Mock notification API response
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Trigger notification update
    const updateButton = page.getByRole('button', { name: /update notifications/i });
    await updateButton.click();

    // Wait for real-time update
    await page.waitForTimeout(500);

    // Verify notifications are updated
    const updatedCount = page.getByRole('region', { name: /notifications/i }).count();
    await expect(updatedCount).toBeGreaterThan(notificationCount);

    // Verify notification content is updated
    const notification = page.getByText(/new notification/i);
    await expect(notification).toBeVisible();

    // Verify notification count is correct
    const notificationCountDisplay = page.getByText(/3 notifications/i);
    await expect(notificationCountDisplay).toBeVisible();

    // Verify notification details are displayed
    const notificationDetails = page.getByText(/urgent message/i);
    await expect(notificationDetails).toBeVisible();

    // Verify notification action button is present
    const actionButton = page.getByRole('button', { name: /view/i });
    await expect(actionButton).toBeVisible();
  });

  test('should handle multiple notifications and display all', async ({ page }) => {
    // Mock multiple notification API responses
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Trigger multiple notifications
    const firstUpdateButton = page.getByRole('button', { name: /update notifications/i });
    await firstUpdateButton.click();

    const secondUpdateButton = page.getByRole('button', { name: /update notifications/i });
    await secondUpdateButton.click();

    // Wait for real-time updates
    await page.waitForTimeout(1000);

    // Verify all notifications are displayed
    const notificationCount = page.getByRole('region', { name: /notifications/i }).count();
    await expect(notificationCount).toBeGreaterThan(0);

    // Verify notification count is correct
    const notificationCountDisplay = page.getByText(/5 notifications/i);
    await expect(notificationCountDisplay).toBeVisible();

    // Verify each notification is visible
    const notifications = page.getByText(/new notification/i);
    const notificationCount = notifications.count();
    await expect(notificationCount).toBeGreaterThan(0);

    // Verify notification details are displayed for each notification
    const notificationDetails = page.getByText(/urgent message/i);
    await expect(notificationDetails).toBeVisible();

    // Verify notification action buttons are present for each notification
    const actionButtons = page.getByRole('button', { name: /view/i });
    await expect(actionButtons).toHaveCount(notificationCount);
  });
});
